package com.example.pdcref;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.NamespacedKey;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Reference: PersistentDataContainer (PDC) patterns for Paper 1.21.
 *
 * KEY RULES:
 *  - Declare one static/instance NamespacedKey per logical field: new NamespacedKey(plugin, "field_name").
 *  - Key names must be lowercase ASCII with no spaces (snake_case is conventional).
 *  - Read with pdc.get(key, type) — returns null if absent; use getOrDefault() to supply a fallback.
 *  - Check pdc.has(key, type) before reading when absence is meaningful.
 *  - PDC on Player / Entity / TileState persists across restarts automatically.
 *  - PDC on ItemStack lives in ItemMeta — call item.setItemMeta(meta) after writing.
 *  - Use TAG_CONTAINER for structured/nested data instead of serialising to JSON strings.
 */
public class PdcRef extends JavaPlugin implements Listener {

    // --- Key declarations ---------------------------------------------------
    // Declare all keys as instance fields initialised in onEnable().
    // Do NOT create NamespacedKey inside event handlers (allocates garbage).
    private NamespacedKey KEY_FIRST_JOIN_TS;  // long  — epoch ms of first join
    private NamespacedKey KEY_KILL_COUNT;     // int   — PvP kill counter
    private NamespacedKey KEY_CUSTOM_ITEM_ID; // string — arbitrary item type tag
    private NamespacedKey KEY_PLAYER_STATS;   // nested container: level + exp

    @Override
    public void onEnable() {
        KEY_FIRST_JOIN_TS  = new NamespacedKey(this, "first_join_ts");
        KEY_KILL_COUNT     = new NamespacedKey(this, "kill_count");
        KEY_CUSTOM_ITEM_ID = new NamespacedKey(this, "custom_item_id");
        KEY_PLAYER_STATS   = new NamespacedKey(this, "player_stats");
        getServer().getPluginManager().registerEvents(this, this);
    }

    // --- Player PDC ---------------------------------------------------------

    @EventHandler
    public void onJoin(PlayerJoinEvent event) {
        Player player = event.getPlayer();
        PersistentDataContainer pdc = player.getPersistentDataContainer();

        // Check-then-set pattern for first-join detection
        if (!pdc.has(KEY_FIRST_JOIN_TS, PersistentDataType.LONG)) {
            pdc.set(KEY_FIRST_JOIN_TS, PersistentDataType.LONG, System.currentTimeMillis());
            player.sendMessage(Component.text("Welcome for the first time!", NamedTextColor.GREEN));
        } else {
            long firstJoin = pdc.get(KEY_FIRST_JOIN_TS, PersistentDataType.LONG);
            player.sendMessage(
                    Component.text("First joined: " + firstJoin, NamedTextColor.GRAY));
        }
    }

    @EventHandler
    public void onDeath(PlayerDeathEvent event) {
        if (!(event.getEntity().getKiller() instanceof Player killer)) return;
        // getOrDefault: safe read with fallback, no null check needed
        PersistentDataContainer pdc = killer.getPersistentDataContainer();
        int kills = pdc.getOrDefault(KEY_KILL_COUNT, PersistentDataType.INTEGER, 0);
        pdc.set(KEY_KILL_COUNT, PersistentDataType.INTEGER, kills + 1);
        killer.sendMessage(Component.text("Kills: " + (kills + 1), NamedTextColor.GOLD));
    }

    // --- ItemStack PDC ------------------------------------------------------

    /** Tag an ItemStack so it can be identified as a custom item by ID. */
    public ItemStack tagItem(ItemStack item, String customId) {
        ItemMeta meta = item.getItemMeta();
        // ItemMeta has its own PDC; always call item.setItemMeta() after writing
        meta.getPersistentDataContainer()
                .set(KEY_CUSTOM_ITEM_ID, PersistentDataType.STRING, customId);
        item.setItemMeta(meta);
        return item;
    }

    /** Return the custom ID tag, or null if the item is not tagged. */
    public String getItemId(ItemStack item) {
        if (item == null || !item.hasItemMeta()) return null;
        return item.getItemMeta()
                .getPersistentDataContainer()
                .get(KEY_CUSTOM_ITEM_ID, PersistentDataType.STRING);
    }

    // --- Nested / structured PDC (TAG_CONTAINER) ----------------------------

    /** Store multi-field structured data in a nested container. */
    public void saveStats(Player player, int level, double exp) {
        PersistentDataContainer root  = player.getPersistentDataContainer();
        // Create a fresh nested container via the adapter context
        PersistentDataContainer stats = root.getAdapterContext().newPersistentDataContainer();
        stats.set(new NamespacedKey(this, "level"), PersistentDataType.INTEGER, level);
        stats.set(new NamespacedKey(this, "exp"),   PersistentDataType.DOUBLE,  exp);
        root.set(KEY_PLAYER_STATS, PersistentDataType.TAG_CONTAINER, stats);
    }

    /** Read back structured stats, returning null if not yet set. */
    public int getLevel(Player player) {
        PersistentDataContainer stats = player.getPersistentDataContainer()
                .get(KEY_PLAYER_STATS, PersistentDataType.TAG_CONTAINER);
        if (stats == null) return 0;
        return stats.getOrDefault(new NamespacedKey(this, "level"), PersistentDataType.INTEGER, 0);
    }
}
